// CORREÇÃO (auditoria v2.1): os valores de client_id, client_secret e
// refresh_token NÃO têm mais fallback hardcoded. Se as variáveis de
// ambiente não estiverem configuradas, o node falha explicitamente em vez
// de tentar autenticar com credenciais antigas/expostas.
//
// O refresh_token do .env (MERCADO_LIVRE_REFRESH_TOKEN) só é usado na
// PRIMEIRA execução, antes de existir qualquer valor salvo no Redis. Nas
// execuções seguintes, o token mais recente (salvo pela última rodada
// deste próprio workflow) tem prioridade.
let storedData = {};
try {
  if ($json.data) {
    storedData = JSON.parse($json.data);
  }
} catch (e) {
  // JSON inválido no Redis é tratado como "sem dado salvo" — segue com env.
}

const clientId = $env.MERCADO_LIVRE_CLIENT_ID;
const clientSecret = $env.MERCADO_LIVRE_CLIENT_SECRET;
const refreshToken = storedData.refresh_token || $env.MERCADO_LIVRE_REFRESH_TOKEN;

if (!clientId || !clientSecret || !refreshToken) {
  throw new Error(
    'Credenciais do Mercado Livre ausentes. Configure MERCADO_LIVRE_CLIENT_ID, ' +
    'MERCADO_LIVRE_CLIENT_SECRET e MERCADO_LIVRE_REFRESH_TOKEN no .env (a última ' +
    'apenas para a primeira execução).'
  );
}

return [{
  json: {
    client_id: clientId,
    client_secret: clientSecret,
    refresh_token: refreshToken
  }
}];

